using System;using System.Collections.Generic;using System.IO;using UnityEngine;using SkyIsland;
public static class PanelReview { public static void Validate(){int n=0;Action<bool,string> check=(ok,name)=>{if(!ok)throw new Exception("PANEL FAIL "+name);n++;};var island=new HexIsland();var panels=new List<PanelState>();var wall=new PanelState{x=1,z=0,vertical=true};check(PanelRules.Add(panels,wall,island),"ground wall supported");panels.Add(wall);check(!PanelRules.Add(panels,new PanelState{x=1,z=1,vertical=true,rotation=2},island),"opposite shared edge duplicate");var floor=new PanelState{x=1,z=0,level=1};check(PanelRules.Add(panels,floor,island),"floor on wall");panels.Add(floor);check(PanelRules.Add(panels,new PanelState{x=2,z=0,level=1},island),"edge floor snap");check(!PanelRules.Add(new List<PanelState>(),floor,island),"floating floor rejected");check(!PanelRules.Validate(new List<PanelState>{floor},island),"support removal rejected");check(PanelRules.Validate(new List<PanelState>{floor,wall},island),"save order independent");check(!PanelRules.Add(panels,new PanelState{x=1,z=0,level=1,rotation=3},island),"rotated floor duplicate");check(!PanelRules.Add(panels,new PanelState{x=1,level=4},island),"level bounds");check(!PanelRules.Add(panels,new PanelState{x=1,rotation=4},island),"rotation bounds");check(!PanelRules.Add(panels,new PanelState{x=100,z=100},island),"ground outside island rejected");check(PanelRules.Blocked(panels,new Vector3(1,1,.5f)),"wall blocks body");check(!PanelRules.Blocked(panels,new Vector3(3,1,3)),"clear movement");check(!PanelRules.Floor(panels,new Vector3(1,-2,0)).HasValue,"no underside floor teleport");check(Mathf.Abs(PanelRules.Floor(panels,new Vector3(1,2.15f,0)).Value-2.15f)<.001f,"walkable floor height");check(PanelRules.Ceiling(panels,new Vector3(1,.5f,0)).HasValue,"ceiling lookup");var inv=new SurvivalInventory(island,new SurvivalState());island.Wood=2;island.Workshops.Add(new Hex(0,1));check(inv.Craft("panel",new Hex(0,0),out _)&&inv.State.panels==1&&island.Wood==0,"panel atomic recipe");check(!inv.Craft("panel",new Hex(0,0),out _)&&inv.State.panels==1,"insufficient no mutation");inv.State.placedPanels=panels;var json=JsonUtility.ToJson(inv.State);var restored=JsonUtility.FromJson<SurvivalState>(json);check(restored.panels==1&&PanelRules.Validate(restored.placedPanels,island),"panel save roundtrip");var motor=new ExplorerMotor(new Vector3(0,1,0));motor.Step(Vector3.right,false,.05f,p=>1,p=>p.x>.1f);check(motor.Position.x==0,"movement resolver blocked");var dropMotor=new ExplorerMotor(new Vector3(0,2.15f,0));dropMotor.Step(Vector3.right,false,.05f,p=>p.x<.1f?(float?)2.15f:1f);check(!dropMotor.Grounded&&dropMotor.Position.y>1f,"step off raised floor falls without teleport");var ceilingMotor=new ExplorerMotor(new Vector3(1,.5f,0));ceilingMotor.Step(Vector3.zero,true,.05f,p=>.5f,null,p=>PanelRules.Ceiling(panels,p));check(Mathf.Abs(ceilingMotor.Position.y-.75f)<.001f&&ceilingMotor.VelocityY==0,"upward jump hits underside");var landing=new ExplorerMotor(new Vector3(1,2.15f,0));landing.Step(Vector3.zero,true,.02f,p=>PanelRules.Floor(panels,p));for(int i=0;i<120;i++)landing.Step(Vector3.zero,false,.02f,p=>PanelRules.Floor(panels,p));check(landing.Grounded&&Mathf.Abs(landing.Position.y-2.15f)<.001f,"jump lands on real floor rules");var turn=new PanelState{x=1};var seen=new HashSet<string>();for(int i=0;i<6;i++){seen.Add(turn.vertical+":"+turn.rotation);var a=turn.Orientation*Vector3.right;var b=turn.Orientation*(Vector3.up*.1f);var c=turn.Orientation*Vector3.forward;var size=new Vector3(Mathf.Abs(a.x)+Mathf.Abs(b.x)+Mathf.Abs(c.x),Mathf.Abs(a.y)+Mathf.Abs(b.y)+Mathf.Abs(c.y),Mathf.Abs(a.z)+Mathf.Abs(b.z)+Mathf.Abs(c.z));check(Vector3.Distance(size,turn.Size)<.001f,"rendered thin-box bounds match collision orientation "+i);turn.RotateNext();}check(seen.Count==6&&!turn.vertical&&turn.rotation==0,"single Q cycles two floors and four walls");var first=new PanelState{x=1};first.RotateNext();check(!first.vertical&&first.rotation==1,"Q changes horizontal grain direction");first.RotateNext();check(first.vertical&&first.rotation==0,"Q changes floor to vertical wall");first.RotateNext();check(Mathf.Abs((first.Orientation*Vector3.up).x)>.99f&&first.Size.x<.11f,"Q changes wall axis with matching bounds");check(PanelRules.Blocked(new List<PanelState>{first},first.Center),"rotated wall blocks");var old=JsonUtility.FromJson<PanelState>("{\"x\":1,\"vertical\":true,\"rotation\":1}");check(old.Key==first.Key&&old.Size==first.Size,"existing saves preserve wall occupancy");Directory.CreateDirectory("../evidence/unity");File.WriteAllText("../evidence/unity/panel-tests.txt","PASS "+n+" panel assertions; local prototype only; UTC "+DateTime.UtcNow.ToString("o"));Debug.Log("SKY_PANEL_TESTS_PASS "+n);}}
